def _safe_get(m: dict, key: str, default: float = 0.0) -> float:
    val = m.get(key)
    if val is None:
        return float(default)
    try:
        f = float(val)
        return f if math.isfinite(f) else float(default)
    except (TypeError, ValueError):
        return float(default)
```
